// Expected JSON: { phone, order_code, total_rupees, delivery_date, slot_name, payment_status }
const o = msg.payload || {};
if (!o.phone || !o.order_code) { msg.statusCode = 400; msg.payload = { error: 'phone and order_code required' }; return [null,msg]; }
msg.customerMessage = `Thank you for ordering from Dhara Water! 💧\nOrder: ${o.order_code}\nTotal: ₹${o.total_rupees ?? 'To be confirmed'}\nDelivery: ${o.delivery_date ?? 'To be scheduled'}\nSlot: ${o.slot_name ?? 'To be confirmed'}\nPayment: ${o.payment_status ?? 'PENDING'}`;
msg.payload = { accepted: true, order_code: o.order_code, message_ready: true, note: 'Connect the WhatsApp Cloud API HTTP Request node to send msg.customerMessage.' };
return [msg,null];
